def rand(*args)
  Kernel.rand(*args)
end

class << Kernel
  alias oldRand rand unless method_defined?(:oldRand)
  def rand(a = nil, b = nil)
    if a.is_a?(Range)
      lo = a.min
      hi = a.max
      return lo + oldRand(hi - lo + 1)
    elsif a.is_a?(Numeric)
      if b.is_a?(Numeric)
        return a + oldRand(b - a + 1)
      else
        return oldRand(a)
      end
    elsif a.nil?
      return oldRand(b)
    end
    return oldRand
  end
end

def has_flag?(flag)
  return @flags.any? { |f| f.downcase == flag.downcase }
end

def register_caught(species)
  species_id = GameData::Species.try_get(species)&.species
  return if species_id.nil?
  @caught_counts[species_id] = 0 if @caught_counts[species_id].nil?
  @caught_counts[species_id] += 1
end
